import math
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from plan_builder import C, E, L, PATH, PL, R, SIGHT  # noqa: E402


def T(de, en):
    return {"de": de, "en": en}


def hooks(items):
    out = []
    for i, (typ, de, en, ode, oen, sc, src) in enumerate(items):
        out.append({"id": f"H{i + 1}", "type": typ, "spoken": T(de, en), "on_screen": T(ode, oen),
                    "scores": dict(zip(("clarity", "relevance", "curiosity", "truth", "visual"), sc)), "source_ids": src,
                    "visual": "", "why": {"truth": "aus den geöffneten Quellen" if sc[3] >= 4 else "nicht belegt, nicht wählbar"}})
    return out


def octagon(cx, cy, r, rot=22.5):
    return [(round(cx + r * math.cos(math.radians(rot + 45 * k)), 1), round(cy + r * math.sin(math.radians(rot + 45 * k)), 1)) for k in range(8)]


# ------------------------------------------------------------------------------------------------ Neuf-Brisach
nb_out, nb_in = octagon(230, 310, 215), octagon(230, 310, 165)
nb_draw = [PL(nb_out, closed=True), PL(nb_in, "ln thin", closed=True)]
for (x1, y1), (x2, y2) in zip(nb_out, nb_out[1:] + nb_out[:1]):           # eight demi-lunes in front of the curtains
    mx, my = (x1 + x2) / 2, (y1 + y2) / 2
    dx, dy = mx - 230, my - 310
    n = math.hypot(dx, dy)
    tip = (round(230 + dx / n * (n + 46), 1), round(310 + dy / n * (n + 46), 1))
    a = (round(mx + (x1 - mx) * 0.35, 1), round(my + (y1 - my) * 0.35, 1))
    b = (round(mx + (x2 - mx) * 0.35, 1), round(my + (y2 - my) * 0.35, 1))
    nb_draw.append(PL([a, tip, b], "ln thin"))
for gx in range(6):
    for gy in range(6):
        x, y = 150 + gx * 28, 230 + gy * 28
        if 2 <= gx <= 3 and 2 <= gy <= 3:
            continue
        nb_draw.append(R(x, y, 22, 22, "ln thin"))
nb_draw += [R(206, 286, 50, 50), C(230, 310, 4, "pivot"), SIGHT(10, 600, 128, 470)]

